-- V90.eu: Reliability Governance + Continuous Improvement Control
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_snapshot(governance_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_key TEXT NOT NULL,target_effectiveness_score NUMERIC NOT NULL DEFAULT 60,realized_effectiveness_score NUMERIC NOT NULL DEFAULT 0,target_breakdown_reduction_pct NUMERIC NOT NULL DEFAULT 0,realized_breakdown_reduction_pct NUMERIC NOT NULL DEFAULT 0,target_downtime_reduction_hours NUMERIC NOT NULL DEFAULT 0,realized_downtime_reduction_hours NUMERIC NOT NULL DEFAULT 0,target_maintenance_cost_impact NUMERIC NOT NULL DEFAULT 0,realized_maintenance_cost_impact NUMERIC NOT NULL DEFAULT 0,approved_actions INTEGER NOT NULL DEFAULT 0,completed_actions INTEGER NOT NULL DEFAULT 0,overdue_actions INTEGER NOT NULL DEFAULT 0,open_change_proposals INTEGER NOT NULL DEFAULT 0,governance_score NUMERIC NOT NULL DEFAULT 0,assessment TEXT NOT NULL DEFAULT 'REVIEW_REQUIRED',recommendation TEXT,status TEXT NOT NULL DEFAULT 'OPEN',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_key));
CREATE INDEX IF NOT EXISTS ix_maintenance_reliability_governance_scope ON maintenance_reliability_governance_snapshot(organization_id,entity_id,period_key,status);
CREATE TABLE IF NOT EXISTS maintenance_reliability_change_proposal(proposal_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_key TEXT NOT NULL,execution_id TEXT,action_id TEXT,work_center_id TEXT,change_type TEXT NOT NULL,proposed_change TEXT NOT NULL,rationale TEXT NOT NULL,target_value NUMERIC,owner_user_id TEXT,due_date DATE,status TEXT NOT NULL DEFAULT 'PROPOSED',decision_note TEXT,approved_by TEXT,approved_at TIMESTAMP,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_maintenance_reliability_change_proposal_scope ON maintenance_reliability_change_proposal(organization_id,entity_id,period_key,status,work_center_id);
CREATE TABLE IF NOT EXISTS maintenance_reliability_governance_close(close_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,period_key TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'CLOSED',closed_by TEXT NOT NULL,closed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,entity_id,period_key));
